'use client';

import { useEffect, useRef, useState } from "react";

export default function Filter() {
    const [selectedLetter, setSelectedLetter] = useState<Set<string>>(new Set());

    const handleClick = (letter: string) => {
        setSelectedLetter(prev => {
        const newSet = new Set(prev);
        newSet.has(letter) ? newSet.delete(letter) : newSet.add(letter);
        return newSet;
        });
    };

    const filters = ["C", "A", "S", "P"];
    return (
        <div className="flex items-center justify-center flex-col gap-5">
            {filters.map((letter) => {
                return (
                <div key={letter} className="flex items-center justify-center bg-[var(--background)] rounded-full transition-all h-[5vh] w-[5vh] hover:h-[10vh] cursor-pointer bubble" onClick={() => handleClick(letter)}>
                    {letter}
                </div>
                );
            })}
        </div>
    );
}